	'upd_req_writable_help' => "PHP работает как «%1\$s» и может только читать эти папки: они принадлежат пользователю, который их загрузил (например, по SFTP), с обычными правами 755 (остальные: только чтение).\nИсправить по SSH (папка: %2\$s):\n• sudo chown -R %1\$s %2\$s – файлы принадлежат PHP (по SFTP тогда только чтение)\n• или совместно: sudo chown -R вашuser:%1\$s %2\$s и chmod 2775 на папки, 664 на файлы\nБез SSH, в SFTP-клиенте (например, FileZilla: правый клик → Права доступа): установить папкам 777 (чтение, запись, выполнение для всех – «выполнение» для папки означает «можно войти»), рекурсивно, только папки. Установить обновление, затем вернуть 755.\nИли обновить вручную: загрузить файлы из nunext.zip поверх старых.",
