	'rd_help' => 'Справка',
	'rd_help_text' => 'Перетащите поля слева на секцию или нажмите Поле / Текст / Прямоугольник / Линия / Изображение. Секции печатаются в таком порядке: заголовок отчёта (один раз), верхний колонтитул (каждая страница), заголовки групп, данные (каждая строка), итоги групп, нижний колонтитул, итог отчёта.\\nПеремещайте объекты мышью (в том числе в другую секцию) или стрелками (Shift = 4 мм, Alt = 0,25 мм); маркеры меняют размер. Shift-щелчок или рамка выделяют несколько объектов, затем кнопки выравнивания.\\nCtrl+Z / Ctrl+Y – отменить и повторить, Ctrl+C / Ctrl+V – копировать, Ctrl+D – дублировать, Del – удалить, Ctrl+S – сохранить.\\nПоля: столбец, SUM(столбец) или AVERAGE(a, b) – суммы по группам сортировки. Тексты могут содержать #page#, #pages#, #code#, #description#, #nu_date# и любую хеш-переменную (например, поля формы запуска).\\nЗначение, начинающееся с #B#rrggbb| или #F#rrggbb|, получает этот цвет фона / текста (условное форматирование из источника данных).\\nПредпросмотр печатает текущий макет с пустыми критериями; макет сохраняется в формате nuBuilder.',
