	'secchk_settings' => 'Настройки безопасности',
	'secchk_set_rights_globeadmin_only' => 'Только globeadmin выдаёт права администратора',
	'secchk_set_rights_globeadmin_only_tip' => 'Права сохранения, добавления, создания, удаления и клонирования в конструкторе форм, процедурах, конструкторе SQL, настройке, пользователях и уровнях доступа дают полный контроль (код на сервере, собственные права). Включено: только globeadmin выдаёт их или назначает уровни доступа с ними; никто другой не изменяет таких пользователей; никто не меняет свой уровень доступа и его права; другие не могут сохранять эти системные формы через формы.',
	'secchk_set_protect_fields' => 'Не сохранять из браузера поля только для чтения и скрытые',
	'secchk_set_protect_fields_tip' => 'Поля с доступом «только чтение» или «скрыто» сохраняют записанное значение, что бы ни отправил браузер. Выключено = как в nuBuilder: JavaScript, заполняющий такие поля (например nuSetValue в скрытом поле), продолжает работать.',
	'secchk_set_record_check' => 'Записи только через список формы',
	'secchk_set_record_check_tip' => 'Запись можно открыть, сохранить или удалить, только если её находит SQL списка формы (с хеш-переменными пользователя). Формы без SQL списка и SQL, которому нужен код Before Browse, не проверяются. Выключено = как в nuBuilder.',
	'secchk_set_md5_login' => 'Принимать старые пароли md5',
