	'secchk_set_log_keep_days' => 'Хранить журнал (дней)',
	'secchk_set_log_keep_days_tip' => 'Более старые записи журнала nuBuilder Next удаляет обслуживание (cron.php или время от времени открытие страницы). 0 = хранить всё.',
	'secchk_set_reauth_minutes' => 'Повторно запрашивать пароль через (минут)',
	'secchk_set_reauth_minutes_tip' => 'Обновление, резервные копии, nuconfig.php, настройки, клонирование приложений, клиенты API, phpMyAdmin / файловый менеджер, «Действовать как пользователь» с полным доступом и эти настройки запрашивают пароль, если вход или последнее подтверждение старше. 0 = никогда не спрашивать.',
