	'secchk_set_reauth_minutes_dev_tip' => 'Только для globeadmin при $nuConfigDevMode = true: разработка ведётся без рабочих данных, поэтому подтверждение пароля действует дольше (по умолчанию 480 = 8 часов). 0 = никогда не спрашивать. Без режима разработчика действует настройка выше.',
